/* v1.1 Phase 8.1 SMOKE kernel (task_plan Phase 8.1 acceptance): a temporary
   elemwise-style carrier used ONLY to verify the non-hash oracle chain
   (classify.py oracle_kind plumbing). NOT a campaign workload.

   Prints all three oracle line formats in one run so a single gem5
   execution exercises every code path:
     ARRAYHASH=<64hex>   (array_hash oracle)
     ELEMDIFF n=<count> first=<idx> maxulp=<n>   (per_element_diff oracle)
     ULP=<max_ulp_error>   (fp_ulp oracle)

   The kernel computes c[i] = a[i]*b[i] + d[i] in double precision twice —
   once on the "golden" arrays and once on the "check" copies — and diffs
   them element-wise. Under an FSU fault injection the check copy diverges
   and the ELEMDIFF/ULP lines report it; with no injection the copies agree
   (n=0, ULP=0). Static AArch64, no libc. --n adjustable via recompile.
*/
#include <unistd.h>
#include <stdint.h>
#include <string.h>

#define N 4096

static double a[N], b[N], d[N], c_golden[N], c_check[N];

static void put(const char *s){ write(1, s, strlen(s)); }
static void put_u64(uint64_t v){
    char buf[20]; int i=19; buf[i--]=0;
    if(!v) buf[i--]='0';
    while(v){ buf[i--]='0'+(v%10); v/=10; }
    write(1, buf+i+1, 18-i);
}
static void put_hex64(uint64_t v){
    char buf[16];
    for(int i=15;i>=0;--i){ unsigned x=v&0xf; buf[i]=x<10?'0'+x:'a'+x-10; v>>=4; }
    write(1,buf,16);
}

/* ULP distance between two doubles (integer repr distance on the IEEE754
   number line; both finite). Good enough for the oracle smoke test. */
static uint64_t ulp_dist(double x, double y){
    if(x==y) return 0;
    uint64_t ux, uy;
    memcpy(&ux,&x,8); memcpy(&uy,&y,8);
    if((ux>>63)!=(uy>>63)){
        /* opposite signs: distance = |x to +0| + |y to -0| + 1 (the two
           zeros are adjacent) */
        uint64_t ax=ux&0x7fffffffffffffffULL, ay=uy&0x7fffffffffffffffULL;
        return ax+ay+1;
    }
    return ux>uy ? ux-uy : uy-ux;
}

int main(void){
    /* deterministic inputs (LCG, same seed for golden and check arrays) */
    uint64_t s=0x243F6A8885A308D3ULL;
    for(int i=0;i<N;i++){
        s=s*6364136223846793005ULL+1442695040888963407ULL;
        a[i]=(double)(s%1000)*0.001+0.5;
        b[i]=(double)((s>>17)%1000)*0.001+0.25;
        d[i]=(double)((s>>33)%1000)*0.001-0.5;
    }
    /* golden pass */
    for(int i=0;i<N;i++) c_golden[i]=a[i]*b[i]+d[i];
    /* check pass: identical data (any divergence is an injected fault) */
    for(int i=0;i<N;i++) c_check[i]=a[i]*b[i]+d[i];

    /* ARRAYHASH: FNV-1a over the raw bytes of c_check */
    uint64_t h=1469598103934665603ULL;
    const unsigned char *p=(const unsigned char*)c_check;
    for(unsigned i=0;i<sizeof(c_check);i++){ h^=p[i]; h*=1099511628211ULL; }
    put("ARRAYHASH="); put_hex64(h); put("\n");

    /* ELEMDIFF + ULP: diff c_check against c_golden */
    uint64_t n_diff=0, first=0, maxulp=0;
    for(int i=0;i<N;i++){
        uint64_t u=ulp_dist(c_check[i],c_golden[i]);
        if(u){ if(!n_diff) first=i; n_diff++; if(u>maxulp) maxulp=u; }
    }
    put("ELEMDIFF n="); put_u64(n_diff);
    put(" first=");     put_u64(first);
    put(" maxulp=");    put_u64(maxulp);
    put("\n");
    put("ULP="); put_u64(maxulp); put("\n");
    return 0;
}

